import {catalog,section,normalize} from './content.js';
import * as db from './db.js';
import {mountScene} from './scene.js';
import {panZoom} from './panzoom.js';
let P=[],PLATES=[],sceneCleanup=null,viewer=null,docViewer=null;
const main=document.querySelector('#main');
const modalRoot=document.querySelector('#modal-root');
const toastEl=document.querySelector('#toast');
let C,viewToken=0,scrollTimer=null,toastTimer=null,selectedRange=null,activeReader=null,focusBeforeDialog=null;
let S={
 prefs:{theme:'marfim',font:'serif',size:19,line:1.8,width:680,motion:true,protected:true,mode:'ilustrado',sfx:true},
 progress:{current:'prologue',anchor:null,completed:[],seen:{},positions:{},lastReader:'prologue',edition:'final'},
 marks:[],discovered:[],letters:[],log:{},places:{},showTitles:false,readerOffset:0,activeAtlas:null
};
const icon={back:'<path d="m15 5-7 7 7 7"/>',toc:'<path d="M4 6h16M4 12h16M4 18h16"/>',setting:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',bookmark:'<path d="M5 3h14v18l-7-5-7 5z"/>',note:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 9h8M8 13h8"/>',close:'<path d="M5 5l14 14M19 5L5 19"/>',next:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m14.5 14.5 6 6"/>'};
function svg(name){return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon[name]||''}</svg>`}
function prose(str){return escapeHTML(str).replace(/\*([^*]+)\*/g,'<em>$1</em>')}
const plain=str=>String(str??'').replace(/\*/g,'');
function escapeHTML(str){return String(str??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]))}
function entry(id){return C.reading.find(x=>x.id===id)}
function linkRead(id){return `#/ler/${id}`}
function currentIndex(id){return C.reading.findIndex(x=>x.id===id)}
function readableSection(item){return !S.prefs.protected||S.progress.completed.includes(item.id)||item.id===S.progress.current||item.type==='prologue'&&S.progress.completed.includes('prologue')}
function safeTitle(item){return readableSection(item)||!S.prefs.protected?item.title:(item.type==='chapter'?`Capítulo ${item.chapter}`:item.type==='letter'?'Correspondência preservada':'Epílogo')}
function reachedChapter(){return Math.max(0,...S.progress.completed.map(x=>entry(x)?.chapter||0))}
function allowedArtifact(a){return !S.prefs.protected||reachedChapter()>=a.minChapter}
function toast(message){clearTimeout(toastTimer);toastEl.textContent=message;toastEl.classList.add('visible');toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),3900)}
function button(label,action,style='button-outline',other=''){return `<button type="button" class="button ${style}" data-action="${action}" ${other}>${label}</button>`}
function setHeadActive(route){document.querySelectorAll('[data-tab]').forEach(a=>{if(a.dataset.tab===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function routeInfo(){let parts=(location.hash||'#/atrio').replace(/^#\/?/,'').split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}});return {route:parts[0]||'atrio',id:parts[1],anchor:parts[2]}}
function navigate(path){location.hash='#/'+path}
async function savePrefs(){try{await db.put('prefs',S.prefs)}catch(e){toast('Não foi possível salvar as preferências: '+e.message)}}
async function saveProgress(){try{await db.put('progress',S.progress)}catch(e){toast('Não foi possível salvar o progresso. Verifique o armazenamento do navegador.')}}
async function saveDiscovered(){try{await db.put('discovered',S.discovered);await db.put('log',S.log);await db.put('places',S.places)}catch{toast('Não foi possível salvar esta descoberta.')}}
function showModal(title,body,onOpen){focusBeforeDialog=document.activeElement;modalRoot.innerHTML=`<div class="scrim" data-scrim="1"><section class="dialog" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="dialog-head"><h2>${escapeHTML(title)}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header>${body}</section></div>`;document.body.style.overflow='hidden';const focusEl=modalRoot.querySelector('textarea,input,button');focusEl?.focus();onOpen?.()}
function closeModal(){docViewer?.destroy();docViewer=null;modalRoot.innerHTML='';document.body.style.overflow='';selectedRange=null;if(focusBeforeDialog?.isConnected)focusBeforeDialog.focus();focusBeforeDialog=null}
function drawer(title,body){focusBeforeDialog=document.activeElement;modalRoot.innerHTML=`<div class="scrim" data-scrim="1"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="drawer-head"><h2>${escapeHTML(title)}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="drawer-body">${body}</div></aside></div>`;document.body.style.overflow='hidden';modalRoot.querySelector('.drawer .icon-button')?.focus()}
function titleCase(s){return s.toLowerCase().replace(/(^|\s)(\S)/g,(m,a,b)=>a+b.toUpperCase()).replace(/ (Da|Do|De|E|O|A|Os|As)(?= )/g,m=>m.toLowerCase())}
function partName(pt){return pt==='Prólogo'?'Prólogo':titleCase(pt.replace(/^PARTE [IVX]+ — /,''))}
function partArt(pt){const i=Object.keys(PART_ART).indexOf(pt);return i<0?'/assets/art/prologue.webp':`/assets/branding/part${i+1}.webp`}
function progressPct(){return Math.round(S.progress.completed.length/C.reading.length*100)}
function hasStarted(){const it=entry(S.progress.current)||C.reading[0];return Boolean(S.progress.completed.length||S.progress.seen[it.id]!=null)}
function updateShell(){if(!C)return;const it=entry(S.progress.current)||C.reading[0],st=hasStarted(),pct=progressPct();const a=document.getElementById('tb-continue');if(a){a.href=linkRead(it.id);document.getElementById('tb-continue-label').textContent=st?`Continuar · ${pct}%`:'Começar';document.getElementById('tb-continue-title').textContent=plain(safeTitle(it));document.getElementById('tb-meter').style.width=pct+'%'}const d=document.getElementById('dock-read');if(d)d.href=linkRead(it.id)}
function pageHeading(eyebrow,title,description,art){return `<header class="room-head${art?' has-art':''}">${art?`<div class="room-head-art" aria-hidden="true"><img src="${art}" alt=""/></div>`:''}<div class="room-head-inner" data-reveal><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div></header>`}
function footer(){return `<footer class="footer"><img class="footer-emblem" src="/assets/branding/emblem-gold.webp" alt="" width="831" height="898" loading="lazy"/>${C?.front?`<p class="footer-quote">${escapeHTML(C.front.epigraph)}<cite>${escapeHTML(C.front.epigraphSource)}</cite></p>`:''}<nav class="footer-nav" aria-label="Rodapé"><a href="#/biblioteca">Biblioteca</a><a href="#/atlas">Atlas</a><a href="#/acervo">Acervo</a><a href="#/galeria">Galeria</a><a href="#/observatorio">Observatório</a><a href="#/config">Configurações</a></nav><p class="footer-sign">Cartas do Norte · O Arquivo Vivo · Uma obra de Werik Martins · Edição Final</p></footer>`}
function frontispiece(){return C.front?`<section class="frontispiece" aria-label="Frontispício"><div class="frontispiece-page"><img class="frontispiece-emblem" src="/assets/branding/emblem-navy.webp" alt="Cartas do Norte" width="809" height="865" loading="lazy"/><p class="frontispiece-sub">${escapeHTML(C.subtitle||'')}</p><p class="frontispiece-author">WERIK MARTINS</p><blockquote>${escapeHTML(C.front.epigraph)}<cite>${escapeHTML(C.front.epigraphSource)}</cite></blockquote><p class="frontispiece-ded">${escapeHTML(C.front.dedication).replace(/\n/g,'<br/>')}</p></div></section>`:''}
function atrioScene(item,started){return `<section class="scene scene-atrio" aria-label="A costa e o farol, aquarela da capa">
   <div class="scene-viewport"><div class="scene-cam"><div class="scene-plate">
     <img class="scene-img" src="/assets/branding/cover.webp" alt="Aquarela da capa: um farol aceso sobre o rochedo, um barco no mar agitado e as luzes de uma vila costeira sob a névoa" fetchpriority="high" decoding="async"/>
     <span class="fx fx-lamp" style="--x:89.6%;--y:35.3%"></span><span class="fx fx-beam" style="--x:89.6%;--y:35.3%"></span><span class="fx fx-glint" style="--x:73.5%;--y:47%"></span>
     ${[[7.5,52.4],[12.2,51],[17.5,52.8],[23.4,53.6],[28.6,54.2],[14.6,48.6],[33.5,55.4]].map(([x,y],i)=>`<span class="fx fx-light" style="--x:${x}%;--y:${y}%;--d:${(i*1.7)%5}s"></span>`).join('')}
     <a class="hotspot hs-end" href="#/cena/farol" style="--x:89.4%;--y:42%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>O farol</strong><small>Entrar na cena viva</small></span></a>
     <a class="hotspot" href="${linkRead(item.id)}" style="--x:55%;--y:63.5%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>A travessia</strong><small>${started?'Continuar a leitura':'Começar a leitura'}</small></span></a>
     <a class="hotspot hs-start" href="#/atlas" style="--x:14%;--y:52%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>A costa</strong><small>Abrir o Atlas</small></span></a>
   </div></div><div class="scene-mist scene-mist-far" aria-hidden="true"></div><div class="scene-mist scene-mist-near" aria-hidden="true"></div><div class="scene-shade" aria-hidden="true"></div></div>
  </section>`}
function renderAtrium(){
 const item=entry(S.progress.current)||C.reading[0],pct=progressPct(),started=hasStarted();
 const letters=C.reading.filter(x=>x.type==='letter');
 const maps=C.artifacts.filter(x=>x.type==='map'),docs=C.artifacts.filter(x=>x.type==='document');
 const art=C.reading.filter(x=>x.art&&(!S.prefs.protected||S.progress.completed.includes(x.id)||x.id===S.progress.current&&S.progress.seen[x.id]!=null)).length;
 const roman=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];
 main.innerHTML=`<div class="atrio">
 <section class="act act-open" data-scrub data-steps=".06,.5" aria-label="Cartas do Norte — O Arquivo Vivo"><div class="act-stage">
  ${atrioScene(item,started)}
  <div class="atrio-copy">
   <span class="kicker"><i aria-hidden="true">✧</i> Um romance · um arquivo · um mar</span>
   <h1 class="visually-hidden">Cartas do Norte — O Arquivo Vivo</h1>
   <img class="atrio-emblem" src="/assets/branding/emblem-gold.webp" alt="Cartas do Norte" width="831" height="898" fetchpriority="high"/>
   <p class="atrio-statement">Há histórias que não terminam na última página.</p>
   <div class="atrio-actions">
    <a class="cta cta-gold" href="${linkRead(item.id)}"><span>${started?'Continuar a leitura':'Começar a leitura'}<small>${started?escapeHTML(plain(safeTitle(item)))+' · '+pct+'%':'Prólogo · a segunda luz'}</small></span><b aria-hidden="true">→</b></a>
    <button class="cta cta-line" type="button" data-action="scroll-salas"><span>Explorar o arquivo<small>Atlas · Acervo · Cenas · Memória</small></span><b aria-hidden="true">↓</b></button>
   </div>
   <button class="atrio-film" type="button" data-action="open-film"><span class="playmark" aria-hidden="true">▶</span> Assistir ao trailer <small>80 s</small></button>
  </div>
  <div class="compass-instrument">
   <button type="button" class="compass-button" data-action="toggle-rose" aria-expanded="false" aria-controls="rose-nav" aria-label="Bússola: navegar pelo arquivo"><img src="/assets/branding/compass.webp" alt="" width="333" height="327"/></button>
   <nav class="rose" id="rose-nav" aria-label="Rosa dos ventos" hidden><a href="#/biblioteca"><small>N</small>Biblioteca</a><a href="#/atlas"><small>L</small>Atlas</a><a href="#/acervo"><small>S</small>Acervo</a><a href="#/observatorio"><small>O</small>Observatório</a></nav>
  </div>
  <div class="act-cue" aria-hidden="true"><span>Role para entrar</span><i></i></div>
 </div></section>

 <section class="act act-light" data-scrub data-steps=".1,.3,.52,.72" aria-label="A primeira luz, do prólogo"><div class="act-stage">
  <img class="light-art" src="/assets/art/prologue.webp" alt="" loading="lazy" aria-hidden="true"/>
  <div class="beacon" aria-hidden="true"><i></i></div>
  <div class="light-lines">
   <p class="line l1">A primeira luz era a que todos esperavam.</p>
   <p class="line l2">Três pulsações sobre o mar, uma pausa, outras três.</p>
   <p class="line l3">A segunda luz não deveria existir.</p>
   <a class="line l4 cta cta-gold" href="#/ler/prologue"><span>Ler o prólogo<small>A segunda luz</small></span><b aria-hidden="true">→</b></a>
  </div>
  <p class="light-source">Do prólogo de <em>Cartas do Norte</em></p>
 </div></section>

 <section class="ways" id="salas" aria-label="Três maneiras de viver o Norte">
  <header class="sec-head" data-reveal><span class="eyebrow">Três maneiras de viver o Norte</span><h2>Ler. Explorar. <em>Sentir.</em></h2></header>
  <div class="ways-grid">
   <a class="way" href="${linkRead(item.id)}" data-reveal><img src="/assets/art/ch1.webp" alt="" loading="lazy"/><span class="way-n" aria-hidden="true">I</span><span class="way-body"><strong>Ler</strong><em>O romance integral em ${C.reading.length} entradas, com aquarelas, cartas e anotações suas.</em><b>${started?'Continuar':'Começar'} a leitura →</b></span></a>
   <a class="way" href="#/atlas" data-reveal><img src="/assets/art/ch5.webp" alt="" loading="lazy"/><span class="way-n" aria-hidden="true">II</span><span class="way-body"><strong>Explorar</strong><em>Cartas náuticas, documentos com lacre e cenas vivas que se abrem com a leitura.</em><b>Abrir o Atlas →</b></span></a>
   <button type="button" class="way" data-action="open-film" data-reveal><img src="/assets/art/prologue.webp" alt="" loading="lazy"/><span class="way-n" aria-hidden="true">III</span><span class="way-body"><strong>Sentir</strong><em>O trailer, a névoa, o mar e o vento: uma camada de atmosfera, só quando você quiser.</em><b>Assistir ao trailer →</b></span></button>
  </div>
 </section>

 <section class="letters" aria-label="As doze cartas">
  <header class="sec-head" data-reveal><span class="eyebrow">Correspondência preservada</span><h2>Doze cartas atravessam a narrativa</h2><p>Como marcas deixadas para quem vem depois. Cada uma se abre quando a leitura chega até ela.</p></header>
  <div class="letters-track" role="list">${letters.map((x,i)=>{const open=!S.prefs.protected||S.progress.completed.includes(x.id)||x.id===S.progress.current;return `<a role="listitem" class="envelope-card ${open?'is-open':''} ${S.progress.completed.includes(x.id)?'is-read':''}" href="${linkRead(x.id)}" data-reveal style="--i:${i}"><span class="env-paper" aria-hidden="true"></span><span class="env-flap" aria-hidden="true"></span><span class="env-seal" aria-hidden="true">${roman[i]}</span><span class="env-text"><small>Carta ${roman[i]} · ${escapeHTML(partName(x.part))}</small><strong>${open?escapeHTML(x.subtitle||x.title):'Lacrada'}</strong><em>${S.progress.completed.includes(x.id)?'Lida':open?'Abrir':'Abre-se na leitura'}</em></span></a>`}).join('')}</div>
 </section>

 <section class="rooms" aria-label="As salas do arquivo">
  <header class="sec-head" data-reveal><span class="eyebrow">O arquivo</span><h2>Há lugares que guardam <em>mais do que um nome.</em></h2></header>
  <div class="rooms-grid">
   <a class="room room-wide" href="#/atlas" data-reveal><img src="/assets/experience/archive-frontispiece.webp" alt="" loading="lazy"/><span class="room-n">${maps.filter(allowedArtifact).length}<small>/${maps.length}</small></span><strong>Atlas</strong><em>cartas da travessia abertas</em></a>
   <a class="room" href="#/acervo" data-reveal><img src="/assets/experience/letter-paper.webp" alt="" loading="lazy"/><span class="room-n">${S.discovered.filter(id=>docs.some(d=>d.id===id)).length}<small>/${docs.length}</small></span><strong>Acervo</strong><em>documentos guardados</em></a>
   <a class="room" href="#/cena/farol" data-reveal><img src="/assets/branding/lighthouse.webp" alt="" loading="lazy"/><span class="room-n">I</span><strong>O farol</strong><em>cena viva</em></a>
   <a class="room" href="#/galeria" data-reveal><img src="/assets/branding/part4.webp" alt="" loading="lazy"/><span class="room-n">${art}<small>/${C.reading.filter(x=>x.art).length}</small></span><strong>Galeria</strong><em>aquarelas encontradas</em></a>
   <a class="room room-wide" href="#/observatorio" data-reveal><img src="/assets/branding/compass.webp" alt="" loading="lazy"/><span class="room-n">${pct}<small>%</small></span><strong>Observatório</strong><em>da travessia concluída</em></a>
  </div>
 </section>

 <section class="trailer-band" aria-label="Trailer">
  <button type="button" class="trailer-play" data-action="open-film" data-reveal><img src="/assets/video/trailer-poster.webp" alt="" loading="lazy"/><span class="play-ring" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></span><span class="trailer-copy"><span class="eyebrow">Trailer · 80 segundos</span><strong>Uma aquarela que respira</strong><em>Assistir com som</em></span></button>
 </section>
 </div>${footer()}`;
 const scene=main.querySelector('.scene-atrio');sceneCleanup=mountScene(scene,{focus:matchMedia('(min-width: 900px)').matches?[0.5,0.5]:[0.62,0.42],intro:true});
}
function renderGallery(){
 const all=C.reading.filter(x=>x.art),visible=all.filter(x=>!S.prefs.protected||S.progress.completed.includes(x.id)||x.id===S.progress.current&&S.progress.seen[x.id]!=null);
 main.innerHTML=`${pageHeading('Galeria','Aquarelas da travessia',`${visible.length} de ${all.length} aquarelas encontradas. As imagens aparecem depois que você as alcança na leitura.`,'/assets/branding/part2.webp')}<div class="gallery"><div class="masonry">${visible.map(x=>`<button type="button" class="watercolor-tile" data-action="view-painting" data-id="${x.id}" data-reveal><img src="${x.art}" loading="lazy" alt="Aquarela de ${escapeHTML(x.title)}"/><span><small>${x.type==='chapter'?'Capítulo '+x.chapter:'Abertura'}</small><strong>${escapeHTML(x.title)}</strong></span></button>`).join('')||'<div class="empty-state"><h2>As primeiras aquarelas aguardam.</h2><p>Comece a leitura para encontrá-las.</p><a class="cta cta-gold" href="#/ler/prologue"><span>Começar pelo prólogo</span><b aria-hidden="true">→</b></a></div>'}</div>${(()=>{const ok=PLATES.filter(x=>!S.prefs.protected||S.progress.completed.includes(x.section)||x.anchor&&x.section===S.progress.current&&S.progress.seen[x.section]);return ok.length?`<section class="gallery-extra"><span class="eyebrow dark">Pranchas da edição · ${ok.length} de ${PLATES.length}</span><div class="plate-grid">${ok.map(x=>`<button type="button" class="plate-tile ${x.w>x.h?'is-wide':''}" data-action="view-plate" data-id="${x.id}"><img src="${x.src}" alt="${escapeHTML(x.alt)}" loading="lazy"/><span>${x.anchor?escapeHTML(entry(x.section)?.title||''):'Prancha avulsa'}</span></button>`).join('')}</div></section>`:''})()}</div>${footer()}`;
}
function renderLibrary(){
 const pct=progressPct(),item=entry(S.progress.current)||C.reading[0],started=hasStarted();
 const parts=[...new Set(C.reading.map(x=>x.part))];
 const card=x=>{const done=S.progress.completed.includes(x.id),cur=x.id===S.progress.current,open=readableSection(x);
  const label=x.type==='chapter'?'Capítulo '+x.chapter:x.title;const name=x.type==='letter'?(open?x.subtitle||x.title:'Correspondência preservada'):x.type==='chapter'?safeTitle(x):(x.subtitle||x.title);
  return `<a class="ch-card t-${x.type} ${done?'is-done':''} ${cur?'is-current':''} ${open?'':'is-sealed'}" href="${linkRead(x.id)}"><span class="ch-art">${open&&x.art?`<img src="${x.art}" alt="" loading="lazy"/>`:`<i aria-hidden="true">${x.type==='letter'?'✉':x.type==='chapter'?String(x.chapter).padStart(2,'0'):'✦'}</i>`}</span><span class="ch-meta"><small>${escapeHTML(label)}</small><strong>${escapeHTML(plain(name))}</strong><em>${done?'Lido ✓':cur?'Em leitura':open?'Abrir':'Não revelado'}</em></span></a>`};
 main.innerHTML=`<div class="library"><header class="lib-hero"><div class="lib-hero-text" data-reveal><span class="eyebrow">Biblioteca · Edição Final</span><h1>O romance</h1><p class="lib-sub">${escapeHTML(C.subtitle)}</p><p>Prólogo, 72 capítulos, 12 cartas e epílogo, na ordem do autor. Nada é bloqueado; no modo protegido, títulos ainda não lidos ficam discretos.</p><div class="lib-progress"><strong>${pct}<small>%</small></strong><span>da travessia concluída</span><i><b style="width:${pct}%"></b></i></div><a class="cta cta-gold" href="${linkRead(item.id)}"><span>${started?'Continuar a leitura':'Começar a leitura'}<small>${escapeHTML(plain(safeTitle(item)))}</small></span><b aria-hidden="true">→</b></a></div>${frontispiece()}</header>
 ${parts.map(pt=>{const items=C.reading.filter(x=>x.part===pt),n=items.filter(x=>S.progress.completed.includes(x.id)).length;return `<section class="lib-part"><div class="lib-part-head" data-reveal><img src="${partArt(pt)}" alt="" loading="lazy"/><div><span class="eyebrow">${pt==='Prólogo'?'Abertura':pt.match(/^PARTE [IVX]+/)[0]}</span><h2>${escapeHTML(partName(pt))}</h2><p>${items.length} entradas · ${n} lidas</p></div></div><div class="lib-grid">${items.map(card).join('')}</div></section>`}).join('')}
 </div>${footer()}`;
}
function renderArchive(){const docs=C.artifacts.filter(x=>x.type==='document'),open=docs.filter(allowedArtifact);
 const letters=LETTERS.map(l=>({l,ok:letterRevealed(l)})),okN=letters.filter(x=>x.ok).length;
 const corr=`<section class="correspondence"><header class="corr-head" data-reveal><span class="eyebrow">Correspondência</span><h2>Cartas reveladas</h2><p>${okN} de ${LETTERS.length} cartas e escritos do romance. Cada um entra aqui quando você o abre na leitura.</p></header><div class="corr-grid">${letters.map(({l,ok},i)=>{const sec=entry(l.section),where=sec?.type==='chapter'?'Capítulo '+sec.chapter:sec?.type==='letter'?escapeHTML(partName(sec.part)):'';return ok?`<button type="button" class="corr-card kind-${l.kind}" data-action="view-letter" data-id="${l.id}" data-reveal style="--i:${i}"><span class="corr-paper" aria-hidden="true"></span>${l.sealed?'<img class="corr-seal" src="/assets/experience/wax-seal.webp" alt=""/>':''}<span class="corr-text"><small>${LETTER_KIND[l.kind]} · ${where}</small><strong>${escapeHTML(l.title)}</strong>${l.to?`<em>${escapeHTML(l.to)}</em>`:''}</span></button>`:`<div class="corr-card is-sealed" data-reveal style="--i:${i}"><span class="corr-paper" aria-hidden="true"></span><img class="corr-seal" src="/assets/experience/wax-seal.webp" alt=""/><span class="corr-text"><small>Lacrada</small><strong>Ainda não aberta</strong><em>${where}</em></span></div>`}).join('')}</div></section>`;
 main.innerHTML=`${pageHeading('Acervo','A mesa do arquivista','Correspondências, registros e objetos da edição. Cada peça guarda sua aparência e uma transcrição acessível; as lacradas se abrem com a leitura.','/assets/experience/letter-paper.webp')}<div class="archive-table">${corr}<h2 class="archive-sub" data-reveal>Documentos e objetos</h2><div class="archive-grid">${docs.map((x,i)=>allowedArtifact(x)?`<button type="button" class="archive-object mat-${x.kind}" data-action="open-artifact" data-id="${x.id}" data-reveal style="--i:${i}"><span class="image-frame"><img src="${x.thumbnail}" alt="Fac-símile de ${escapeHTML(x.title)}" loading="lazy"/></span><span class="object-label"><small>${KIND_LABEL[x.kind]}${S.discovered.includes(x.id)?' · guardado':''}</small><strong>${escapeHTML(x.title)}</strong></span></button>`:`<div class="archive-object is-sealed" data-reveal style="--i:${i}"><span class="image-frame"><span class="vestige-seal" aria-hidden="true">✦</span></span><span class="object-label"><small>Peça lacrada</small><strong>Abre-se no capítulo ${x.minChapter}</strong></span></div>`).join('')}</div><p class="archive-note">${open.length} de ${docs.length} peças abertas. Os mapas ficam no <a href="#/atlas">Atlas</a>.</p></div>${footer()}`}

async function render(){
 const token=++viewToken;sceneCleanup?.();sceneCleanup=null;viewer?.destroy();viewer=null;const {route,id,anchor}=routeInfo();setHeadActive(route==='ler'?'biblioteca':route);document.body.classList.toggle('is-reading',route==='ler');main.removeAttribute('data-view');
 try{
  if(route==='atrio')renderAtrium();
  else if(route==='biblioteca')renderLibrary();
  else if(route==='ler')await renderReader(id||S.progress.current,anchor,token);
  else if(route==='acervo')renderArchive();
  else if(route==='atlas')renderAtlas(id,anchor);
  else if(route==='observatorio')renderObservatory();
  else if(route==='galeria')renderGallery();
  else if(route==='config')renderConfig();
  else if(route==='busca')renderSearch();
  else if(route==='cena')await renderScene(id,token);
  else{navigate('atrio');return}
  if(token!==viewToken)return;
  main.dataset.view=route;updateShell();
  if(route!=='ler'){window.scrollTo(0,0)}
 }catch(err){console.error(err);if(token!==viewToken)return;main.innerHTML=`<div class="page-container empty-state"><h2>Não foi possível abrir esta parte do arquivo.</h2><p>${escapeHTML(err.message)}</p><a class="button button-primary" href="#/atrio">Voltar ao Átrio</a></div>`}
}
function countWords(x){return x.blocks.reduce((t,b)=>t+b.text.split(/\s+/).length,0)}
function applyHighlightToParagraph(element,notes){
 const raw=element.textContent||'';if(!notes.length)return;
 const spans=notes.filter(n=>n.start>=0&&n.end<=raw.length&&n.end>n.start).sort((a,b)=>a.start-b.start);
 let offset=0;const fragment=document.createDocumentFragment();
 for(const note of spans){if(note.start<offset)continue;fragment.append(document.createTextNode(raw.slice(offset,note.start)));const mark=document.createElement('mark');mark.textContent=raw.slice(note.start,note.end);mark.title=note.note||'Destaque salvo';fragment.append(mark);offset=note.end}
 fragment.append(document.createTextNode(raw.slice(offset)));element.replaceChildren(fragment)
}
const PART_ART={'PARTE I — A COSTA':1,'PARTE II — AS ÁGUAS PROFUNDAS':2,'PARTE III — A TEMPESTADE':3,'PARTE IV — O FAROL':4};
// Aquarelas que recebem atmosfera própria: chuva apenas onde a pintura já mostra chuva.
const RAIN=new Set(['prologue','ch1']);
function reducedMotion(){return !S.prefs.motion||matchMedia('(prefers-reduced-motion: reduce)').matches}
function reachedIndex(){return Math.max(-1,...S.progress.completed.map(currentIndex))}
function placeKnown(p){return !S.prefs.protected||p.firstIndex<=Math.max(reachedIndex(),currentIndex(S.progress.current))}
function partLabel(part){const m=part.match(/^PARTE ([IVX]+) — /);return m?{n:m[1]}:{n:''}}
// ── Cartas: objetos que se abrem durante a leitura ─────────────────────────
let LETTERS=[];
const LETTER_KIND={carta:'Carta',bilhete:'Bilhete',folha:'Folha manuscrita',declaracao:'Declaração'};
function letterOpen(l){return S.letters.includes(l.id)}
function letterRevealed(l){return letterOpen(l)||!S.prefs.protected||S.progress.completed.includes(l.section)}
function sealMarkup(l,size=''){return `<button type="button" class="wax ${size}" data-action="break-seal" data-letter="${l.id}" aria-label="Romper o selo e abrir ${escapeHTML(l.title)}"><img class="wax-l" src="/assets/experience/wax-seal-l.webp" alt=""/><img class="wax-r" src="/assets/experience/wax-seal-r.webp" alt=""/></button>`}
function envelopeMarkup(l,roman){return `<div class="envelope-stage" aria-hidden="false"><div class="envelope"><div class="env-back"></div><div class="env-letter" aria-hidden="true"></div><div class="env-front"><span class="env-kicker">${roman?escapeHTML(l.title).toUpperCase():LETTER_KIND[l.kind].toUpperCase()}</span>${l.to?`<span class="env-address">${escapeHTML(l.to)}</span>`:''}</div><div class="env-flap"></div>${sealMarkup(l)}</div><span class="env-hint">Toque no selo para abrir</span></div>`}
function paperOpen(cls=''){return `<div class="paper ${cls}"><span class="paper-top" aria-hidden="true"></span><div class="paper-body">`}
const paperClose='</div><span class="paper-bot" aria-hidden="true"></span></div>';
async function saveLetters(){try{await db.put('letters',S.letters)}catch{}}
async function markLetter(id,silent){if(S.letters.includes(id))return;S.letters=[...S.letters,id];await saveLetters();if(!silent)toast('Carta guardada no Acervo · Correspondência.')}
let sfxCtx=null;
function letterSfx(){if(S.prefs.sfx===false)return;try{sfxCtx??=new AudioContext();const c=sfxCtx,t=c.currentTime,n=c.sampleRate*.9,b=c.createBuffer(1,n,c.sampleRate),d=b.getChannelData(0);
 for(let i=0;i<n;i++){const s=i/c.sampleRate;const crack=s<.06?(Math.random()*2-1)*Math.exp(-s*70):0;const rustle=s>.18?(Math.random()*2-1)*.22*Math.exp(-(s-.18)*4)*(.6+.4*Math.sin(s*90)):0;d[i]=crack*.9+rustle}
 const src=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();f.type='bandpass';f.frequency.value=2200;f.Q.value=.6;g.gain.value=.35;src.buffer=b;src.connect(f).connect(g).connect(c.destination);src.start(t)}catch{}}
async function breakSeal(id){const l=LETTERS.find(x=>x.id===id);if(!l)return;const els=main.querySelectorAll(`[data-letter-id="${id}"]`);letterSfx();
 els.forEach(el=>{el.classList.add('is-opening');el.querySelectorAll('[hidden]').forEach(h=>h.hidden=false)});
 const done=()=>els.forEach(el=>{el.classList.remove('is-opening','is-sealed');el.classList.add('is-open');el.querySelector('.envelope-stage')?.setAttribute('aria-hidden','true')});
 if(reducedMotion())done();else setTimeout(done,1700);
 await markLetter(id);const first=els[0]?.querySelector('[data-block-id]');setTimeout(()=>first?.focus?.({preventScroll:true}),reducedMotion()?0:1500)}
function decorateLetters(root){root.querySelectorAll('.paper-text').forEach(pt=>{const ps=[...pt.querySelectorAll('p:not(.letter-to)')];if(!ps.length)return;const last=ps.at(-1);if(last.textContent.trim().length<=26)last.classList.add('sig');const f=ps[0];if(/,$/.test(f.textContent.trim())&&f.textContent.length<40)f.classList.add('salute')})}
function letterStateFor(l,anchor,blockIds){return letterOpen(l)||!l.sealed||(anchor&&blockIds.includes(anchor))}

async function letterBlocks(l){const data=await section(l.section);const paras=data.blocks.filter(b=>b.type==='para'||b.type==='rule');if(l.whole)return paras;const ids=paras.map(b=>b.id);return l.spans.flatMap(([a,z])=>paras.slice(ids.indexOf(a),ids.indexOf(z)+1))}
async function viewLetter(id){const l=LETTERS.find(x=>x.id===id);if(!l||!letterRevealed(l))return;if(!letterOpen(l))await markLetter(id,true);const bl=await letterBlocks(l),sec=entry(l.section);
 focusBeforeDialog=document.activeElement;docViewer?.destroy();docViewer=null;
 modalRoot.innerHTML=`<div class="viewer viewer-letter" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><header class="viewer-head"><div class="viewer-title"><span class="eyebrow">Correspondência · ${escapeHTML(sec?.type==='chapter'?'Capítulo '+sec.chapter:sec?.title||'')}</span><h2 id="viewer-title">${escapeHTML(l.title)}${l.to?' · '+escapeHTML(l.to):''}</h2></div><a class="button button-outline button-small viewer-read" href="${linkRead(l.section)}/${bl.find(b=>b.type==='para')?.id||''}">Ler no romance ↗</a><button class="icon-button viewer-close" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="letter-desk">${paperOpen('paper-'+l.kind)}<div class="paper-text">${l.whole?`<header class="letter-head"><span class="letter-kicker">${escapeHTML(l.title).toUpperCase()}</span><p class="letter-to">${escapeHTML(l.to)}</p></header>`:''}<div class="letter-prose">${bl.map(b=>b.type==='rule'?'<div class="endmark" aria-hidden="true">✧</div>':`<p>${prose(b.text)}</p>`).join('')}</div></div>${paperClose}</div></div>`;
 document.body.style.overflow='hidden';decorateLetters(modalRoot);modalRoot.querySelector('.viewer-close').focus()}
async function renderReader(id,anchor,token){
 const meta=entry(id);if(!meta)throw Error('Este capítulo não consta do índice editorial.');
 main.innerHTML='<div class="loading-splash"><span class="load-star">✧</span><p>Abrindo páginas…</p></div>';
 const content=await section(id);if(token!==viewToken)return;
 S.progress.current=id;S.progress.lastReader=id;await saveProgress();if(token!==viewToken)return;
 activeReader=id;const idx=currentIndex(id),next=C.reading[idx+1],previous=C.reading[idx-1];
 const chosenAnchor=anchor||S.progress.positions?.[id]||(S.progress.anchor&&S.progress.anchor.section===id?S.progress.anchor.id:null);
 const related=meta.chapter?C.artifacts.filter(x=>x.minChapter===meta.chapter):[];
 const contentBlocks=content.blocks.filter((b,i)=>!(i===0&&b.type==='h2'&&normalize(b.text)===normalize(content.title)));
 const plateAt=Object.fromEntries(S.prefs.mode!=='foco'?PLATES.filter(x=>x.section===id&&x.anchor).map(x=>[x.anchor,x]):[]);
 const plateFig=x=>`<figure class="plate living ${x.w>x.h?'is-wide':'is-tall'}"><div class="living-frame"><img src="${x.src}" width="${x.w}" height="${x.h}" loading="lazy" alt="${escapeHTML(x.alt)}"/></div><span class="living-mist" aria-hidden="true"></span><figcaption>${escapeHTML(x.caption)}</figcaption></figure>`;
 const para=b=>b.type==='rule'?'<div class="endmark" aria-hidden="true">✧</div>':b.type==='para'?`<p data-block-id="${b.id}" id="${b.id}" tabindex="-1">${prose(b.text)}</p>${plateAt[b.id]?plateFig(plateAt[b.id]):''}`:`<h${b.type==='h3'?3:2}>${escapeHTML(b.text)}</h${b.type==='h3'?3:2}>`;
 const inline=LETTERS.filter(l=>!l.whole&&l.section===id),startAt={},ids=contentBlocks.map(b=>b.id);
 for(const l of inline)l.spans.forEach(([a,z],k)=>startAt[a]={l,k,z});
 let paragraphs='';
 for(let i=0;i<contentBlocks.length;i++){const s0=startAt[contentBlocks[i].id];if(!s0){paragraphs+=para(contentBlocks[i]);continue}
  const {l,k,z}=s0,j=ids.indexOf(z),inner=contentBlocks.slice(i,j+1),allIds=l.spans.flatMap(([a,b])=>ids.slice(ids.indexOf(a),ids.indexOf(b)+1));
  const open=letterStateFor(l,chosenAnchor,allIds),sealedFirst=l.sealed&&k===0;
  paragraphs+=`<div class="inline-letter kind-${l.kind} ${open?'is-open':'is-sealed'} ${k?'is-continued':''}" data-letter-id="${l.id}" role="group" aria-label="${escapeHTML(l.title)}">${sealedFirst?envelopeMarkup(l,false):''}${paperOpen('paper-'+l.kind)}<div class="paper-text"${open?'':' hidden'}>${inner.map(para).join('')}</div>${paperClose}</div>`;
  i=j}
 const illustrated=S.prefs.mode!=='foco';
 const minutes=Math.max(1,Math.round(content.blocks.reduce((t,b)=>t+b.text.split(/\s+/).length,0)/220));
 const kind=content.type==='chapter'?'CAPÍTULO '+meta.chapter:content.type==='letter'?'CORRESPONDÊNCIA PRESERVADA':content.type==='prologue'?'ABERTURA':'ENCERRAMENTO';
 const partNo=PART_ART[meta.part],newPart=partNo&&(!previous||previous.part!==meta.part),pl=partLabel(meta.part||'');
 const plate=illustrated&&newPart?`<section class="part-plate" aria-label="${escapeHTML(meta.part)}"><img src="/assets/branding/part${partNo}.webp" alt="Página de abertura da ${escapeHTML(meta.part.toLowerCase())}, em aquarela sobre papel" loading="eager"/><div class="part-plate-title"><span>PARTE ${pl.n}</span><strong>${escapeHTML(meta.part.replace(/^PARTE [IVX]+ — /,''))}</strong></div></section>`:'';
 const opening=illustrated&&meta.art?`<header class="opening has-art"><figure class="opening-art living ${RAIN.has(id)?'is-rain':''}"><div class="living-frame"><img src="${meta.art}" width="584" height="875" alt="Aquarela editorial aprovada para ${escapeHTML(meta.title)}" fetchpriority="high"/></div><span class="living-mist" aria-hidden="true"></span>${RAIN.has(id)?'<span class="living-rain" aria-hidden="true"></span>':''}<figcaption>Aquarela da edição · ${content.type==='chapter'?'Capítulo '+meta.chapter:escapeHTML(meta.title)}</figcaption></figure><div class="opening-title"><span class="eyebrow">${kind}</span><h1>${escapeHTML(content.title)}</h1>${content.subtitle?`<div class="subtitle">${escapeHTML(content.subtitle)}</div>`:''}<div class="ornamental-rule" aria-hidden="true">✧</div><p class="opening-meta">${escapeHTML((meta.part||'').replace(/^PARTE ([IVX]+) — /,'Parte $1 · '))} · cerca de ${minutes} min</p><button type="button" class="opening-begin" data-action="begin-reading">Começar a ler <span aria-hidden="true">↓</span></button></div></header>`:`<header class="reader-opening"><span class="eyebrow">${kind}</span><h1>${escapeHTML(content.title)}</h1>${content.subtitle?`<div class="subtitle">${escapeHTML(content.subtitle)}</div>`:''}<div class="ornamental-rule" aria-hidden="true">✧</div></header>`;
 const L1=meta.type==='letter'?LETTERS.find(x=>x.id===id):null;
 const letterOpenNow=L1&&(letterOpen(L1)||chosenAnchor&&content.blocks.some(b=>b.id===chosenAnchor)||S.progress.completed.includes(id));
 const vestiges=related.length?`<section class="vestige-shelf"><div class="eyebrow dark">Vestígios deste capítulo</div>${related.map(a=>allowedArtifact(a)?`<button type="button" class="vestige-card" data-action="open-artifact" data-id="${a.id}" data-from="ler"><span class="vestige-thumb mat-${a.kind}"><img src="${a.thumbnail}" alt="" loading="lazy"/></span><span><small>${KIND_LABEL[a.kind]}${S.discovered.includes(a.id)?' · guardado':''}</small><strong>${escapeHTML(a.title)}</strong><em>${S.discovered.includes(a.id)?'Examinar novamente':'Examinar e guardar no seu acervo'} ↗</em></span></button>`:`<div class="vestige-card is-sealed"><span class="vestige-seal" aria-hidden="true">✦</span><span><small>Vestígio lacrado</small><strong>Uma peça do arquivo aguarda o fim deste capítulo.</strong></span></div>`).join('')}</section>`:'';
 const cited=P.filter(p=>p.mentions.includes(id)&&placeKnown(p));
 const places=cited.length?`<section class="place-chips"><div class="eyebrow dark">Lugares citados</div>${cited.map(p=>`<a href="${p.name==='Farol da Vigília'?'#/cena/farol':'#/atlas/-/'+encodeURIComponent(p.name)}">${escapeHTML(p.name)} <span aria-hidden="true">↗</span></a>`).join('')}</section>`:'';
 main.innerHTML=`<div class="reader-shell mode-${illustrated?'ilustrado':'foco'}" data-reader-theme="${S.prefs.theme}"><div class="reader-header"><a class="reader-back" href="#/biblioteca" aria-label="Voltar à biblioteca">←</a><button class="icon-button" data-action="reader-toc" aria-label="Abrir sumário" title="Sumário">${svg('toc')}</button><div class="reader-heading">${escapeHTML(content.title)}</div><span class="reader-prog" id="reader-percent">0%</span><button class="icon-button" data-action="bookmark" aria-label="Salvar marcador" title="Marcador">${svg('bookmark')}</button><button class="icon-button" data-action="reader-notes" aria-label="Anotações" title="Anotações">${svg('note')}</button><button class="icon-button" data-action="reader-settings" aria-label="Configurar leitura" title="Aparência">${svg('setting')}</button><div class="reader-progress-line" id="reader-progress-line" style="width:0%"></div></div>${plate}<article class="reader-prose" id="reader-article" aria-label="${escapeHTML(content.title)}">${L1?`<section class="whole-letter ${letterOpenNow?'is-open':'is-sealed'}" data-letter-id="${L1.id}"><p class="letter-part">${escapeHTML((meta.part||'').replace(/^PARTE ([IVX]+) — /,'Parte $1 · '))}</p>${envelopeMarkup(L1,true)}${paperOpen('paper-carta')}<div class="paper-text"${letterOpenNow?'':' hidden'}><header class="letter-head"><span class="letter-kicker">${escapeHTML(L1.title).toUpperCase()}</span><p class="letter-to">${escapeHTML(L1.to)}</p></header><div class="reader-text letter-prose" id="read-start">${paragraphs}</div></div>${paperClose}</section>`:`${opening}<div class="reader-text" id="read-start">${paragraphs}</div>`}<div class="reader-end"><span class="ornamental-rule" style="justify-content:center" aria-hidden="true">✧</span><p>Fim de ${content.title.toLowerCase()}.</p><div class="reader-end-buttons">${previous?`<a class="button button-outline button-small" href="${linkRead(previous.id)}">← Anterior</a>`:''}${button(S.progress.completed.includes(id)?'Concluído ✓':'Marcar como concluído','complete','button-outline button-small')}${next?`<button type="button" class="button button-primary button-small" data-action="next-section" data-next="${next.id}">Continuar →</button>`:''}</div>${vestiges}${places}<p class="reader-progress-meter">${idx+1} de ${C.reading.length} entradas de leitura</p></div></article></div>`;
 applyPrefs();
 watchLiving();
 watchLetters();
 decorateLetters(main);
 for(const para of main.querySelectorAll('[data-block-id]'))applyHighlightToParagraph(para,S.marks.filter(m=>m.type==='highlight'&&m.section===id&&m.anchor===para.dataset.blockId));
 if(chosenAnchor){requestAnimationFrame(()=>{const el=document.getElementById(chosenAnchor);if(el)el.scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo(0,0)})}
 else window.scrollTo(0,0);
 window.removeEventListener('scroll',onReaderScroll);window.addEventListener('scroll',onReaderScroll,{passive:true});requestAnimationFrame(updateReadingPosition);
}
// Aquarelas vivas só se movem enquanto estão visíveis.
function watchLetters(){if(!('IntersectionObserver' in window))return;const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const id=e.target.dataset.letterId,l=LETTERS.find(x=>x.id===id);if(l&&!l.sealed)markLetter(id,true);io.unobserve(e.target)}}),{threshold:.4});main.querySelectorAll('.inline-letter.is-open').forEach(el=>io.observe(el));const prev=sceneCleanup;sceneCleanup=()=>{prev?.();io.disconnect()}}
function watchLiving(){const els=main.querySelectorAll('.living,.part-plate');if(!els.length||!('IntersectionObserver' in window))return;const io=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('is-live',e.isIntersecting)),{threshold:.05});els.forEach(el=>io.observe(el));const prev=sceneCleanup;sceneCleanup=()=>{prev?.();io.disconnect()}}
function nearestParagraph(){const paras=[...main.querySelectorAll('#reader-article [data-block-id]')];if(!paras.length)return null;return paras.find(p=>p.getBoundingClientRect().bottom>Math.max(120,innerHeight*.24))||paras.at(-1)}
function updateReadingPosition(){if(!main.querySelector('#reader-article'))return;const p=nearestParagraph(),id=activeReader;if(!p||!id)return;const all=[...main.querySelectorAll('#reader-article [data-block-id]')];const index=all.indexOf(p);S.progress.anchor={section:id,id:p.dataset.blockId};S.progress.positions??={};S.progress.positions[id]=p.dataset.blockId;S.progress.seen[id]=Math.max(index,S.progress.seen[id]??0);
 const article=document.querySelector('#reader-article');if(!article)return;const rect=article.getBoundingClientRect();const viewHeight=innerHeight-130;const total=Math.max(1,article.offsetHeight-viewHeight);const pct=Math.max(0,Math.min(100,Math.round((-rect.top)/total*100)));document.querySelector('#reader-percent').textContent=pct+'%';document.querySelector('#reader-progress-line').style.width=pct+'%';}
function onReaderScroll(){if(routeInfo().route!=='ler')return;clearTimeout(scrollTimer);scrollTimer=setTimeout(async()=>{updateReadingPosition();await saveProgress()},350)}
async function completeReading(){const id=activeReader;if(!id)return;S.progress.completed=[...new Set([...S.progress.completed,id])];await saveProgress();toast('Leitura concluída. Seu progresso foi preservado.');await render()}
function applyPrefs(){const p=S.prefs;document.documentElement.style.setProperty('--reading-size',p.size+'px');document.documentElement.style.setProperty('--reading-line',p.line);document.documentElement.style.setProperty('--reading-width',p.width+'px');document.documentElement.style.setProperty('--reading-font',p.font==='sans'?'system-ui, sans-serif':p.font==='classic'?"'Cormorant Garamond',Georgia,serif":"'Newsreader',Georgia,serif");document.body.classList.toggle('reduce-motion',!p.motion);const shell=document.querySelector('.reader-shell');if(shell)shell.dataset.readerTheme=p.theme}
function readingSettingsMarkup(){const p=S.prefs;return `<div class="settings-group"><h3>Modo de leitura</h3><div class="segmented">${[['ilustrado','Livro ilustrado'],['foco','Foco']].map(([key,t])=>`<button type="button" data-action="pref" data-pref="mode" data-value="${key}" aria-pressed="${(p.mode||'ilustrado')===key}">${t}</button>`).join('')}</div><p class="fineprint">Foco esconde aquarelas e aberturas, deixando só o texto.</p></div><div class="settings-group"><h3>Atmosfera de leitura</h3><div class="segmented">${[['marfim','Marfim'],['sepia','Sépia'],['noite','Noite']].map(([key,t])=>`<button type="button" data-action="pref" data-pref="theme" data-value="${key}" aria-pressed="${p.theme===key}">${t}</button>`).join('')}</div></div><div class="settings-group"><h3>Tipografia</h3><div class="setting-row"><label for="pref-font">Família</label><select id="pref-font" data-pref="font"><option value="serif" ${p.font==='serif'?'selected':''}>Editorial</option><option value="classic" ${p.font==='classic'?'selected':''}>Clássica</option><option value="sans" ${p.font==='sans'?'selected':''}>Sem serifa</option></select></div><div class="setting-row"><label for="pref-size">Tamanho: <span id="size-label">${p.size}px</span></label><input id="pref-size" data-pref="size" type="range" min="15" max="28" value="${p.size}"/></div><div class="setting-row"><label for="pref-line">Entrelinha</label><select id="pref-line" data-pref="line">${[1.5,1.65,1.8,2].map(x=>`<option value="${x}" ${p.line==x?'selected':''}>${x.toString().replace('.',',')}×</option>`).join('')}</select></div><div class="setting-row"><label for="pref-width">Largura do texto</label><select id="pref-width" data-pref="width">${[[550,'Estreita'],[680,'Confortável'],[800,'Ampla']].map(([x,t])=>`<option value="${x}" ${p.width==x?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="settings-group"><h3>Experiência</h3><div class="setting-row"><label for="pref-motion">Transições suaves</label><input type="checkbox" id="pref-motion" data-pref="motion" ${p.motion?'checked':''}/></div><div class="setting-row"><label for="pref-sfx">Som ao abrir cartas</label><input type="checkbox" id="pref-sfx" data-pref="sfx" ${p.sfx!==false?'checked':''}/></div><div class="setting-row"><label for="pref-protected">Modo protegido contra spoilers</label><input type="checkbox" id="pref-protected" data-pref="protected" ${p.protected?'checked':''}/></div><p class="fineprint">No modo protegido, mapas e documentos somente são revelados após a conclusão do capítulo correspondente.</p></div>`}
function readerSettings(){drawer('Leitura',readingSettingsMarkup()+`<p class="fineprint">As preferências são salvas neste dispositivo. Não é preciso criar conta.</p>`) }
function tableOfContents(){let rows='',last='';for(const x of C.reading){if(x.part!==last){last=x.part;rows+=`<h3 class="toc-section-title">${escapeHTML(last)}</h3>`}rows+=`<a class="toc-row ${x.id===activeReader?'current':''}" href="${linkRead(x.id)}">${escapeHTML(safeTitle(x))}${S.progress.completed.includes(x.id)?' ✓':''}</a>`}drawer('Índice de leitura',rows)}
async function setBookmark(){const sectionId=activeReader, anchor=nearestParagraph()?.dataset.blockId||null;if(!sectionId)return;const key='bookmark-'+sectionId;const old=S.marks.find(m=>m.id===key);if(old){await db.remove(key,'marks');S.marks=S.marks.filter(m=>m.id!==key);toast('Marcador removido.')}else{const m={id:key,type:'bookmark',section:sectionId,anchor,created:new Date().toISOString()};await db.put(key,m,'marks');S.marks.push(m);toast('Marcador salvo.')}}
function readerNotes(){const marks=S.marks.filter(m=>m.section===activeReader);let contents=marks.map(m=>`<div class="note-item"><small>${m.type==='bookmark'?'MARCADOR':m.type==='highlight'?'DESTAQUE':'NOTA'} · ${new Date(m.created).toLocaleDateString('pt-BR')}</small>${m.text?`<p>“${escapeHTML(m.text.slice(0,190))}”</p>`:''}${m.note?`<p>${escapeHTML(m.note)}</p>`:''}<div><button class="button button-quiet" data-action="jump-mark" data-id="${escapeHTML(m.id)}">Ir ao trecho</button><button class="button button-quiet" data-action="delete-mark" data-id="${escapeHTML(m.id)}">Excluir</button></div></div>`).join('');if(!contents)contents='<div class="empty-state"><h2>Sem anotações</h2><p>Selecione um trecho durante a leitura para destacar ou comentar. Use o ícone de marcador para guardar um ponto.</p></div>';drawer('Suas marcas',contents)}
function handleSelection(){if(routeInfo().route!=='ler')return;const selection=document.getSelection();if(!selection||selection.isCollapsed||selection.toString().trim().length<2)return;const start=selection.anchorNode?.parentElement?.closest('[data-block-id]');const end=selection.focusNode?.parentElement?.closest('[data-block-id]');if(!start||start!==end||!main.contains(start))return;const range=selection.getRangeAt(0).cloneRange();const pre=range.cloneRange();pre.selectNodeContents(start);pre.setEnd(range.startContainer,range.startOffset);const index=pre.toString().length;const text=range.toString();selectedRange={section:activeReader,anchor:start.dataset.blockId,start:index,end:index+text.length,text};document.getElementById('mark-toolbar')?.remove();const node=document.createElement('div');node.className='mark-toolbar';node.id='mark-toolbar';node.innerHTML='<button data-action="add-highlight">Destacar trecho</button><button data-action="add-note">Anotar</button><button data-action="hide-selection" aria-label="Fechar ações de seleção">✕</button>';document.body.append(node)}
function hideSelection(){document.getElementById('mark-toolbar')?.remove();document.getSelection()?.removeAllRanges()}
async function saveMark(type,note=''){if(!selectedRange)return;const m={...selectedRange,type,note,created:new Date().toISOString(),id:'mark-'+crypto.randomUUID()};await db.put(m.id,m,'marks');S.marks.push(m);hideSelection();closeModal();toast(type==='highlight'?'Trecho destacado.':'Anotação salva.');if(routeInfo().route==='ler')await render()}
function notesDialog(){if(!selectedRange){toast('Selecione primeiro um trecho do texto.');return}hideSelection();showModal('Anotação',`<p class="fineprint">“${escapeHTML(selectedRange.text.slice(0,320))}”</p><label for="note-text">Sua anotação</label><textarea id="note-text" placeholder="Escreva o que este trecho despertou…"></textarea><div class="dialog-actions"><button class="button button-outline" data-action="close-modal">Cancelar</button><button class="button button-primary" data-action="save-note">Salvar anotação</button></div>`)}
const KIND_LABEL={carta:'Correspondência pessoal',diario:'Diário',testamento:'Testamento','registro-maritimo':'Registro marítimo',registro:'Registro',oficial:'Documento oficial',juridico:'Documento jurídico',manuscrito:'Manuscrito',prancha:'Prancha técnica',transmissao:'Transmissão',objeto:'Objeto preservado',mapa:'Cartografia'};
const SEALED=new Set(['carta','manuscrito','testamento','oficial','juridico']);
function zoomControls(){return `<div class="viewer-zoom" role="group" aria-label="Ampliação"><button type="button" data-action="zoom-out" aria-label="Reduzir">−</button><output class="zoom-out-label" aria-live="polite">100%</output><button type="button" data-action="zoom-in" aria-label="Ampliar">+</button><button type="button" data-action="zoom-reset">Ajustar</button></div>`}
const zoomLabel=root=>s=>{const o=root.querySelector('.zoom-out-label');if(o)o.textContent=Math.round(s*100)+'%'};
async function recordDiscovery(x,from){if(S.discovered.includes(x.id))return false;S.discovered=[...S.discovered,x.id];S.log[x.id]={at:new Date().toISOString(),from:from==='ler'&&activeReader?activeReader:null};await saveDiscovered();return true}
async function openArtifact(id,from){const x=C.artifacts.find(x=>x.id===id);if(!x)return;if(!allowedArtifact(x)){toast('Este vestígio ainda não foi revelado. Conclua o capítulo relacionado ou use o modo livre.');return}
 const isNew=await recordDiscovery(x,from);
 focusBeforeDialog=document.activeElement;docViewer?.destroy();
 const sealed=SEALED.has(x.kind)&&!reducedMotion();
 modalRoot.innerHTML=`<div class="viewer mat-${x.kind}" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><header class="viewer-head"><div class="viewer-title"><span class="eyebrow">${KIND_LABEL[x.kind]} · página ${x.sourcePage} da edição</span><h2 id="viewer-title">${escapeHTML(x.title)}</h2></div><div class="viewer-tabs" role="group" aria-label="Alternar vista"><button type="button" data-action="viewer-tab" data-tab="img" aria-pressed="true">Fac-símile</button><button type="button" data-action="viewer-tab" data-tab="text" aria-pressed="false">Transcrição</button></div><button class="icon-button viewer-close" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="viewer-body" data-tab="img"><div class="viewer-stage"><div class="pz-frame" tabindex="0" aria-label="Fac-símile ampliável. Use mais e menos para ampliar, setas para mover, ou o gesto de pinça."><div class="pz-layer"><img src="${x.image}" alt="Fac-símile editorial aprovado: ${escapeHTML(x.title)}"/></div></div>${zoomControls()}</div><aside class="viewer-text"><span class="eyebrow dark">Transcrição</span><p class="transcription-status">Extraída do PDF da edição v4 · em revisão editorial, não definitiva</p><div class="transcription" id="viewer-transcription">Carregando…</div><p class="fineprint">${escapeHTML(x.provenance)}. ${isNew?'<strong>Guardado agora no seu acervo pessoal.</strong>':'Já faz parte do seu acervo pessoal.'}</p><div class="viewer-actions"><button type="button" class="button button-primary" data-action="close-modal">${from==='ler'?'← Voltar ao ponto da leitura':'Voltar'}</button>${x.type==='map'?`<a class="button button-outline" href="#/atlas/${x.id}">Ver no Atlas</a>`:''}</div></aside></div>${sealed?`<div class="seal-intro"><div class="envelope" aria-hidden="true"><span class="flap"></span><span class="wax"><b>CN</b></span></div><button type="button" class="seal-skip" data-action="skip-seal">Abrir diretamente</button></div>`:''}</div>`;
 document.body.style.overflow='hidden';
 docViewer=panZoom(modalRoot.querySelector('.pz-frame'),{onChange:zoomLabel(modalRoot)});
 const seal=modalRoot.querySelector('.seal-intro');if(seal){modalRoot.querySelector('.seal-skip').focus();setTimeout(()=>skipSeal(),1500)}else modalRoot.querySelector('.viewer-close').focus();
 if(isNew)toast('Vestígio guardado no seu acervo.');
 try{const r=await fetch(`/content/artifacts/${x.id}.json`);if(!r.ok)throw Error();const t=await r.json();const el=document.getElementById('viewer-transcription');if(el)el.textContent=t.transcription}catch{const el=document.getElementById('viewer-transcription');if(el)el.textContent='Transcrição indisponível neste momento. O fac-símile continua acessível.'}
}
function skipSeal(){const seal=modalRoot.querySelector('.seal-intro');if(!seal)return;const hadFocus=seal.contains(document.activeElement);seal.remove();if(hadFocus)modalRoot.querySelector('.pz-frame')?.focus()}

// Passagens do romance que citam um nome, apenas em trechos já autorizados pelo modo protegido.
async function passagesFor(name,limit=6){const rec=P.find(p=>p.name===name)||PEOPLE.find(p=>p.name===name);const q=normalize(rec?.term||name),out=[];
 for(const id of (rec?.mentions||[])){const item=entry(id);if(!item)continue;
  const done=S.progress.completed.includes(id),cur=id===S.progress.current;if(S.prefs.protected&&!done&&!cur)continue;
  const data=await section(id);const upper=S.prefs.protected&&!done?(S.progress.seen[id]??-1):Infinity;
  for(const [i,b] of data.blocks.entries()){if(b.type!=='para'||i>upper)continue;const t=plain(b.text),k=normalize(t).indexOf(q);if(k<0)continue;out.push({item,id:b.id,text:t.slice(Math.max(0,k-110),k+170),cut:k>110});break}
  if(out.length>=limit)break}
 return out}
function passageList(list,name){return list.length?list.map(x=>`<a class="passage" href="${linkRead(x.item.id)}/${x.id}"><small>${x.item.type==='chapter'?'Capítulo '+x.item.chapter:escapeHTML(x.item.title)} · ${escapeHTML(safeTitle(x.item))}</small><span>${x.cut?'…':''}${escapeHTML(x.text).replace(new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i'),m=>`<mark>${m}</mark>`)}…</span></a>`).join(''):'<p class="fineprint">Os registros deste lugar aparecem conforme a leitura avança.</p>'}

function renderAtlas(mapId,placeName){const maps=C.artifacts.filter(x=>x.type==='map'),available=maps.filter(allowedArtifact);
 if(placeName&&(!mapId||mapId==='-')){const m=[...available].reverse().find(m=>m.labels.some(l=>l.name===placeName));if(m)mapId=m.id}
 const sel=available.find(x=>x.id===mapId)||available.find(x=>x.id===S.activeAtlas)||available.at(-1);
 if(!sel){main.innerHTML=`${pageHeading('Cartografia','O Atlas','As cartas náuticas da edição são reveladas conforme a leitura avança.')}<div class="page-container section-content"><div class="atlas-sealed"><img src="/assets/experience/archive-frontispiece.webp" alt="Frontispício cartográfico ornamental, sem localidades" loading="lazy"/><div><h2>A primeira carta aguarda sua leitura.</h2><p>Conclua o primeiro capítulo para abrir a primeira carta da travessia.</p><a class="button button-primary" href="#/ler/ch1">Ir ao capítulo 1 →</a></div></div></div>${footer()}`;return}
 S.activeAtlas=sel.id;
 const known=P.filter(placeKnown),knownNames=new Set(known.map(p=>p.name));
 const pins=sel.labels.filter(l=>sel.id==='gruta_map'||knownNames.has(l.name)).map(l=>`<button type="button" class="pin ${S.places[l.name]?'is-visited':''}" style="left:${l.x}%;top:${l.y}%" data-action="atlas-place" data-name="${escapeHTML(l.name)}"><span class="visually-hidden">${escapeHTML(l.name)}</span></button>`).join('');
 const onMap=known.filter(p=>sel.labels.some(l=>l.name===p.name)),offMap=known.filter(p=>!sel.labels.some(l=>l.name===p.name));
 const placeBtn=p=>`<button type="button" class="place-btn ${S.places[p.name]?'is-visited':''}" data-action="atlas-place" data-name="${escapeHTML(p.name)}" aria-pressed="${p.name===placeName}">${escapeHTML(p.name)}<small>${S.places[p.name]?'visitado':'primeira menção: '+escapeHTML(safeTitle(entry(p.first)))}</small></button>`;
 main.innerHTML=`<div class="atlas-page"><header class="atlas-head"><span class="eyebrow">Cartografia da travessia · ${available.length} de ${maps.length} cartas abertas</span><h1>O Atlas</h1><p>Cartas da edição de colecionador. As marcas indicam lugares que você já encontrou na leitura e aproximam o mapa do nome impresso, sem coordenadas inventadas.</p></header><div class="atlas-layout"><div class="atlas-stage"><div class="pz-frame" tabindex="0" aria-label="${escapeHTML(sel.title)}: mapa ampliável. Pinça, roda do mouse com Ctrl, duplo clique ou teclas mais e menos."><div class="pz-layer"><img src="${sel.image}" alt="Mapa aprovado: ${escapeHTML(sel.title)}"/>${pins}</div></div>${zoomControls()}<p class="atlas-caption">${escapeHTML(sel.title)} · ${escapeHTML(sel.provenance)} · revelado após o capítulo ${sel.minChapter}</p></div><aside class="atlas-panel"><div class="atlas-maps" role="group" aria-label="Escolher carta">${maps.map(m=>allowedArtifact(m)?`<a class="atlas-map ${m.id===sel.id?'is-current':''}" href="#/atlas/${m.id}" ${m.id===sel.id?'aria-current="true"':''}><img src="${m.thumbnail}" alt="" loading="lazy"/><span>${escapeHTML(m.title)}</span></a>`:`<span class="atlas-map is-sealed" aria-label="Carta lacrada"><span class="vestige-seal" aria-hidden="true">✦</span><span>Carta lacrada</span></span>`).join('')}</div><div id="place-detail" class="place-detail" aria-live="polite"><p class="fineprint">Escolha uma localidade para aproximar a carta e ler o que o romance diz dela.</p></div><h2 class="atlas-sub">Lugares nesta carta</h2><div class="place-list">${onMap.map(placeBtn).join('')||'<p class="fineprint">Nenhum lugar desta carta foi encontrado na leitura ainda.</p>'}</div>${offMap.length?`<h2 class="atlas-sub">Outros lugares conhecidos</h2><div class="place-list">${offMap.map(placeBtn).join('')}</div>`:''}<p class="fineprint atlas-actions"><button type="button" class="button button-outline button-small" data-action="open-artifact" data-id="${sel.id}">Examinar fac-símile e transcrição</button></p></aside></div></div>${footer()}`;
 viewer=panZoom(main.querySelector('.atlas-page .pz-frame'),{wheel:'ctrl',onChange:zoomLabel(main)});
 if(placeName)requestAnimationFrame(()=>showPlace(placeName));
}
async function showPlace(name){const p=P.find(x=>x.name===name),sel=C.artifacts.find(x=>x.id===S.activeAtlas);const label=sel?.labels.find(l=>l.name===name);
 if(label&&viewer){viewer.focus(label.x,label.y,2.6);main.querySelectorAll('.pin').forEach(b=>b.classList.toggle('is-active',b.dataset.name===name))}
 main.querySelectorAll('.place-btn').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.name===name)));
 const box=document.getElementById('place-detail');if(!box)return;
 if(!p){box.innerHTML=`<h3>${escapeHTML(name)}</h3><p class="fineprint">Rótulo impresso nesta carta.</p>`;return}
 if(!placeKnown(p)){box.innerHTML='<p class="fineprint">Este lugar ainda não apareceu na sua leitura.</p>';return}
 if(!S.places[name]){S.places[name]={at:new Date().toISOString()};saveDiscovered()}
 const otherMaps=p.maps.filter(id=>id!==S.activeAtlas).map(id=>C.artifacts.find(a=>a.id===id)).filter(a=>a&&allowedArtifact(a));
 box.innerHTML=`<span class="eyebrow dark">Localidade</span><h3>${escapeHTML(name)}</h3><p class="fineprint">${label?'Aproximado no nome impresso nesta carta.':'Este nome não aparece nesta carta.'} Primeira menção: ${escapeHTML(safeTitle(entry(p.first)))}.</p>${name==='Farol da Vigília'?'<a class="button button-primary button-small" href="#/cena/farol">Entrar na cena viva ↗</a>':''}${otherMaps.length?`<p class="fineprint">Também em: ${otherMaps.map(m=>`<a href="#/atlas/${m.id}/${encodeURIComponent(name)}">${escapeHTML(m.title)}</a>`).join(' · ')}</p>`:''}<div class="passages">Consultando o romance…</div>`;
 const list=await passagesFor(name,4);const el=box.querySelector('.passages');if(el)el.innerHTML=passageList(list,name)}

async function renderScene(id,token){if(id!=='farol'){navigate('atrio');return}
 const map=C.artifacts.find(a=>a.id==='map_stage_1'),mapOk=allowedArtifact(map),item=entry(S.progress.current)||C.reading[0];
 main.innerHTML=`<div class="scene-page"><section class="scene scene-farol" aria-label="Cena viva: o farol"><div class="scene-viewport"><div class="scene-cam"><div class="scene-plate"><img class="scene-img" src="/assets/branding/cover.webp" alt="Detalhe da aquarela da capa: o farol aceso sobre o rochedo, com a casa ao lado e o mar batendo nas pedras"/><span class="fx fx-lamp" style="--x:89.6%;--y:35.3%"></span><span class="fx fx-beam" style="--x:89.6%;--y:35.3%"></span><span class="fx fx-glint" style="--x:73.5%;--y:47%"></span><a class="hotspot hs-end" href="#/cena/farol" data-action="scroll-records" style="--x:89.6%;--y:37%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>A lanterna</strong><small>O que o romance diz do farol</small></span></a>${mapOk?`<a class="hotspot hs-end" href="#/atlas/map_stage_1/${encodeURIComponent('Farol da Vigília')}" style="--x:80%;--y:56%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>O rochedo</strong><small>Localizar na carta da costa</small></span></a>`:''}<a class="hotspot" href="${linkRead(item.id)}" style="--x:55%;--y:63.5%"><span class="hotspot-dot" aria-hidden="true"></span><span class="hotspot-label"><strong>O barco</strong><small>Voltar à leitura</small></span></a></div></div><div class="scene-mist scene-mist-far" aria-hidden="true"></div><div class="scene-mist scene-mist-near" aria-hidden="true"></div><div class="scene-shade" aria-hidden="true"></div></div><div class="scene-panel"><span class="eyebrow">Cena viva · I</span><h1>O farol</h1><p>Uma aproximação da aquarela da capa. Os pontos de luz levam ao que o arquivo guarda sobre este lugar.</p><div class="scene-actions"><button type="button" class="button button-primary" data-action="scroll-records">O que o romance diz</button><button type="button" class="button button-outline scene-sound" data-action="scene-sound" data-sound="vento" aria-pressed="false">Ouvir o vento</button></div><p class="scene-note">Ambientação a partir da capa aprovada. O texto não identifica esta pintura como o Farol da Vigília; os registros abaixo vêm do romance.</p></div><p class="scene-hint" aria-hidden="true"><span class="hint-desk">Mova o cursor para olhar · os pontos de luz levam a algum lugar</span><span class="hint-touch">Arraste para olhar · toque nos pontos de luz</span></p></section><section class="scene-records" id="registros"><div class="page-container"><span class="eyebrow dark">Registros do arquivo · Farol da Vigília</span><h2>O que o romance diz</h2><div class="passages">Consultando o romance…</div></div></section></div>${footer()}`;
 sceneCleanup=mountScene(main.querySelector('.scene-farol'),{focus:[0.86,0.4],zoom:matchMedia('(min-width: 900px)').matches?1.25:1.5});
 const list=await passagesFor('Farol da Vigília',8);if(token!==viewToken)return;const el=main.querySelector('.scene-records .passages');if(el)el.innerHTML=passageList(list,'Farol da Vigília')}

let PEOPLE=[];
async function openPerson(name){const p=PEOPLE.find(x=>x.name===name);if(!p||!placeKnown(p))return;focusBeforeDialog=document.activeElement;docViewer?.destroy();docViewer=null;
 modalRoot.innerHTML=`<div class="viewer viewer-person" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><header class="viewer-head"><div class="viewer-title"><span class="eyebrow">Pessoas encontradas · retrato da edição</span><h2 id="viewer-title">${escapeHTML(p.name)}</h2></div><button class="icon-button viewer-close" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="person-body"><figure class="person-figure"><img src="${p.figure||p.portrait}" alt="Retrato em aquarela de ${escapeHTML(p.name)}"/>${p.signature?`<img class="person-signature" src="${p.signature}" alt="Assinatura de Jonas Vale"/>`:''}</figure><div class="person-text"><p class="fineprint">Primeira menção: <a href="${linkRead(p.first)}">${escapeHTML(safeTitle(entry(p.first)))}</a> · ${p.mentions.filter(id=>!S.prefs.protected||S.progress.completed.includes(id)).length} entrada(s) lida(s) com este nome.</p><h3>O que o romance diz</h3><div class="passages">Consultando o romance…</div></div></div></div>`;
 document.body.style.overflow='hidden';modalRoot.querySelector('.viewer-close').focus();
 const list=await passagesFor(name,5);const el=modalRoot.querySelector('.person-text .passages');if(el)el.innerHTML=passageList(list,p.term||name)}
function renderObservatory(){const done=S.progress.completed.length,percentage=Math.round(done/C.reading.length*100);
 const people=PEOPLE.filter(placeKnown);const known=P.filter(placeKnown);
 const found=S.discovered.map(id=>C.artifacts.find(x=>x.id===id)).filter(Boolean).filter(allowedArtifact);const sealed=C.artifacts.length-found.length;
 const parts=Object.keys(PART_ART).map(part=>{const items=C.reading.filter(x=>x.part===part);const n=items.filter(x=>S.progress.completed.includes(x.id)).length;return {part,n,t:items.length}});
 const date=d=>d?new Date(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'';
 const notes=S.marks.filter(m=>m.type!=='bookmark').slice(-4).reverse();
 main.innerHTML=`<div class="observatory-page"><header class="obs-head"><div><span class="eyebrow">Sala de memória</span><h1>O Observatório</h1><p>O que a sua leitura já revelou: lugares, pessoas, vestígios e marcas. Nada aqui antecipa o que ainda não foi lido.</p></div><div class="obs-meter"><strong>${percentage}<span>%</span></strong><small>${done} de ${C.reading.length} entradas concluídas</small></div></header><section class="obs-parts" aria-label="Progresso por parte">${parts.map((p,i)=>`<div class="obs-part"><img src="/assets/branding/part${i+1}.webp" alt="" loading="lazy"/><span>PARTE ${['I','II','III','IV'][i]}</span><strong>${escapeHTML(p.part.replace(/^PARTE [IVX]+ — /,''))}</strong><div class="progress-track"><span style="width:${Math.round(p.n/p.t*100)}%"></span></div><small>${p.n} de ${p.t}</small></div>`).join('')}</section><section class="obs-section"><div class="obs-title"><span class="eyebrow dark">Coleção pessoal</span><h2>Vestígios guardados</h2><p>${found.length} guardados · ${sealed} ainda no arquivo</p></div><div class="obs-vestiges">${found.map(x=>`<button type="button" class="vestige-card" data-action="open-artifact" data-id="${x.id}"><span class="vestige-thumb mat-${x.kind}"><img src="${x.thumbnail}" alt="" loading="lazy"/></span><span><small>${KIND_LABEL[x.kind]} · capítulo ${x.minChapter}</small><strong>${escapeHTML(x.title)}</strong><em>${S.log[x.id]?'Guardado em '+date(S.log[x.id].at)+(S.log[x.id].from?' · durante '+escapeHTML(entry(S.log[x.id].from)?.title||''):''):'Guardado'}</em></span></button>`).join('')||'<div class="empty-state"><p>Os documentos e mapas que você examinar ficam guardados aqui.</p><a class="button button-outline" href="#/acervo">Abrir o Acervo</a></div>'}</div></section><div class="obs-grid"><section class="obs-section"><span class="eyebrow dark">Cartografia</span><h2>Lugares conhecidos</h2>${known.map(p=>`<a class="obs-line" href="${p.name==='Farol da Vigília'?'#/cena/farol':'#/atlas/-/'+encodeURIComponent(p.name)}"><strong>${escapeHTML(p.name)}</strong><small>${S.places[p.name]?'visitado no Atlas · ':''}${p.mentions.filter(id=>!S.prefs.protected||S.progress.completed.includes(id)).length} menção(ões) lidas</small></a>`).join('')||'<p class="fineprint">Os lugares aparecem conforme você lê.</p>'}</section><section class="obs-section"><span class="eyebrow dark">Pessoas encontradas</span><h2>Personagens</h2><div class="people-grid">${people.map(x=>x.portrait?`<button type="button" class="person-card" data-action="open-person" data-name="${escapeHTML(x.name)}"><img src="${x.portrait}" alt="Retrato de ${escapeHTML(x.name)}" loading="lazy"/><strong>${escapeHTML(x.name)}</strong></button>`:`<div class="person-card is-plain"><span aria-hidden="true">${escapeHTML(x.name[0])}</span><strong>${escapeHTML(x.name)}</strong></div>`).join('')||'<p class="fineprint">Os nomes aparecem conforme você lê.</p>'}</div><p class="fineprint">Retratos da edição, nome e primeira menção no texto. Sem perfis nem destinos.</p></section><section class="obs-section"><span class="eyebrow dark">Caderno</span><h2>Suas marcas</h2>${notes.map(m=>`<a class="obs-line" href="${linkRead(m.section)}/${m.anchor}"><strong>“${escapeHTML((m.text||'').slice(0,90))}”</strong><small>${m.note?escapeHTML(m.note.slice(0,80)):'destaque'} · ${escapeHTML(entry(m.section)?.title||'')}</small></a>`).join('')||'<p class="fineprint">Selecione um trecho durante a leitura para destacar ou anotar.</p>'}<a class="text-link" href="#/galeria">Galeria de aquarelas ↗</a></section></div></div>${footer()}`}

function renderSearch(){main.innerHTML=`${pageHeading('Índice remissivo','Buscar no Arquivo','Procure títulos, palavras e passagens do romance. O modo protegido exclui trechos ainda não alcançados e elementos futuros.')}<div class="page-container section-content"><form id="search-form" class="search-form"><input id="search-input" autocomplete="off" required minlength="2" placeholder="Palavra, frase ou nome…" aria-label="Termo de busca"/><button class="button button-primary" type="submit">Buscar →</button></form><p class="fineprint">${S.prefs.protected?'Modo protegido ativo: apenas capítulos concluídos e parágrafos já alcançados do capítulo atual.':'Modo livre ativo: busca em toda a obra.'}</p><div id="search-results" class="search-results"></div></div>${footer()}`;main.querySelector('#search-input')?.focus()}
async function performSearch(query){const dest=document.querySelector('#search-results');if(!dest)return;const q=normalize(query).trim();if(q.length<2){dest.innerHTML='<p>Digite pelo menos dois caracteres.</p>';return}dest.innerHTML='<p class="fineprint">Consultando as entradas autorizadas…</p>';const oldToken=viewToken;let hits=[],searched=0;
 for(const item of C.reading){if(oldToken!==viewToken)return;
  if(S.prefs.protected&&!S.progress.completed.includes(item.id)&&item.id!==S.progress.current)continue;
  const data=await section(item.id);searched++;
  const upper=S.prefs.protected&&!S.progress.completed.includes(item.id)?(S.progress.seen[item.id]??-1):Infinity;
  for(const [i,b] of data.blocks.entries()){if(b.type==='h1'||b.type==='h2'||i>upper)continue;
   const index=normalize(b.text).indexOf(q);if(index<0)continue;const snippet=plain(b.text).slice(Math.max(0,index-85),index+Math.max(130,q.length+60));hits.push({meta:item,id:b.id,snippet});if(hits.length>=35)break}
  if(hits.length>=35)break;
 }
 if(oldToken!==viewToken)return;dest.innerHTML=`<p class="fineprint">${hits.length} resultado(s) · ${searched} entrada(s) consultada(s) ${hits.length>=35?'· exibindo os primeiros 35':''}</p>`+ (hits.length?hits.map(x=>`<article class="search-hit"><small>${x.meta.type==='chapter'?'Capítulo '+x.meta.chapter:'Correspondência e paratextos'}</small><div><a href="${linkRead(x.meta.id)}/${x.id}">${escapeHTML(x.meta.title)} ↗</a></div><p>…${escapeHTML(x.snippet)}…</p></article>`).join(''):`<div class="empty-state"><h2>Nenhuma passagem encontrada</h2><p>Tente outra expressão ou continue lendo. No modo protegido, trechos futuros não são pesquisados.</p></div>`)}
function renderConfig(){main.innerHTML=`<div class="setting-screen"><span class="eyebrow dark">Preferências e preservação</span><h1>Configurações</h1><p>O seu caderno de leitura permanece neste navegador, sem conta ou envio de anotações para um servidor.</p>${readingSettingsMarkup()}<div class="settings-group"><h3>Seu arquivo pessoal</h3><p class="fineprint">Exporte um arquivo JSON para preservar marcadores, anotações e progresso. Importe para restaurá-los em outro dispositivo.</p><div class="settings-page-actions">${button('Exportar dados','export-data','button-primary button-small')}${button('Importar dados','import-data','button-outline button-small')}${button('Apagar dados locais','clear-data','button-outline button-small danger')}</div><input type="file" accept="application/json,.json" hidden id="import-file" aria-label="Escolher arquivo JSON de backup"/></div><div class="settings-group"><h3>Leitura offline</h3><p class="fineprint">Prepare o texto e a interface para uso sem internet. Ilustrações grandes e documentos podem ser baixados separadamente, se houver espaço.</p>${button('Preparar leitura offline','offline-text','button-primary button-small')} ${button('Preparar imagens e mapas','offline-media','button-outline button-small')}<p id="offline-status" class="fineprint" aria-live="polite"></p></div><div class="settings-group"><h3>Progresso de leitura</h3><p class="fineprint">Você pode registrar manualmente como concluído o capítulo atual sem perder os outros registros. O romance nunca é bloqueado.</p>${button('Concluir entrada atual','manual-complete','button-outline button-small')}<p class="fineprint">Entrada atual: ${escapeHTML(entry(S.progress.current)?.title||'Prólogo')}</p></div><p class="fineprint">Versão 0.5 · Texto da Edição Final do autor.</p></div>${footer()}`;applyPrefs()}
async function modifyPref(pref,value){if(!['theme','font','size','line','width','motion','protected','mode','sfx'].includes(pref))return;
 if(pref==='protected'&&value===false&&S.prefs.protected){
  showModal('Exploração livre',`<p>O modo livre permite consultar mapas, documentos e passagens ainda não alcançados. Isso pode revelar acontecimentos importantes do romance.</p><div class="dialog-actions"><button class="button button-outline" data-action="close-modal">Manter proteção</button><button class="button button-primary" data-action="confirm-free">Ativar modo livre</button></div>`);return;
 }
 S.prefs[pref]=value;await savePrefs();applyPrefs();if(routeInfo().route==='config')renderConfig();else if(routeInfo().route==='ler'&&modalRoot.querySelector('.drawer')){if(pref==='mode'){closeModal();await render()}else readerSettings()}else await render();}
async function exportData(){const value={schema:'cartas-do-norte-leitor',version:1,exportedAt:new Date().toISOString(),prefs:S.prefs,progress:S.progress,marks:S.marks,discovered:S.discovered,log:S.log,places:S.places,letters:S.letters};const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cartas-do-norte-meu-arquivo.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);toast('Arquivo de leitura exportado.')}
async function importData(file){if(!file)return;try{if(file.size>8e6)throw Error('O arquivo é grande demais.');const obj=JSON.parse(await file.text());if(obj.schema!=='cartas-do-norte-leitor'||obj.version!==1||!Array.isArray(obj.marks)||!obj.prefs||!obj.progress||!Array.isArray(obj.discovered))throw Error('Formato de backup incompatível.');if(!entry(obj.progress.current))throw Error('Progresso sem entrada válida.');S.prefs={...S.prefs,...obj.prefs};S.progress={...S.progress,...obj.progress};S.marks=obj.marks.filter(m=>m.id&&m.section&&entry(m.section)).slice(0,20000);S.discovered=obj.discovered.filter(v=>C.artifacts.some(a=>a.id===v));S.log=obj.log&&typeof obj.log==='object'?obj.log:{};S.letters=Array.isArray(obj.letters)?obj.letters.filter(x=>LETTERS.some(l=>l.id===x)):[];S.places=obj.places&&typeof obj.places==='object'?obj.places:{};await db.reset();await Promise.all([savePrefs(),saveProgress(),saveDiscovered(),saveLetters()]);for(const m of S.marks)await db.put(m.id,m,'marks');toast('Arquivo pessoal restaurado.');render()}catch(e){toast('Não foi possível importar: '+e.message)}}
async function prepareOffline(kind){const status=document.querySelector('#offline-status');if(!('caches' in window)||!('serviceWorker' in navigator)){if(status)status.textContent='Este navegador não oferece preparação offline segura neste contexto. Use HTTPS ou localhost.';return}
 const files=kind==='text'?['/','/index.html','/src/motion.js','/src/main.js','/src/scene.js','/src/panzoom.js','/src/ui.css','/content/places.json','/content/people.json','/content/plates.json','/assets/experience/letter-paper.webp','/content/letters.json','/assets/fonts/charis.woff2','/assets/fonts/charis-italic.woff2','/assets/fonts/pinyon-script.woff2','/assets/experience/wax-seal.webp','/assets/experience/wax-seal-l.webp','/assets/experience/wax-seal-r.webp','/assets/experience/paper-top.webp','/assets/experience/paper-mid.webp','/assets/experience/paper-bot.webp','/assets/fonts/newsreader.woff2','/assets/fonts/newsreader-italic.woff2','/assets/fonts/cormorant-400.woff2','/assets/fonts/cormorant-400-italic.woff2','/assets/fonts/cormorant-500.woff2','/assets/fonts/cormorant-600.woff2','/src/ambience.js','/src/db.js','/src/content.js','/content/catalog.json','/manifest.webmanifest',...C.reading.map(x=>`/content/reading/${x.id}.json`)]:['/assets/branding/cover.webp','/assets/experience/archive-frontispiece.webp','/assets/experience/edition-paper.webp','/assets/branding/compass.webp','/assets/branding/cartographic-frontispiece.webp','/assets/branding/part1.webp','/assets/branding/lighthouse.webp','/assets/video/trailer.mp4','/assets/video/trailer-poster.webp','/assets/video/trailer.vtt','/assets/experience/mist.webp',...[1,2,3,4].map(n=>`/assets/branding/part${n}.webp`),...C.artifacts.map(x=>`/content/artifacts/${x.id}.json`),'/assets/audio/mar.ogg','/assets/audio/chuva.ogg','/assets/audio/vento.ogg',...C.reading.filter(x=>x.art).map(x=>x.art),...C.artifacts.flatMap(x=>[x.image,x.thumbnail])];
 try{const cache=await caches.open('arquivo-vivo-offline-v1');for(let i=0;i<files.length;i++){const r=await fetch(files[i]);if(!r.ok)throw Error('Falha ao baixar '+files[i]);await cache.put(files[i],r);if(status)status.textContent=`Preparando ${kind==='text'?'textos':'imagens e sons'}: ${i+1} de ${files.length} arquivos.`}if(status)status.textContent=`${files.length} recursos armazenados. A leitura offline está preparada neste dispositivo.`;toast('Preparação offline concluída.')}catch(e){if(status)status.textContent='Não foi possível concluir: '+e.message;toast('Download offline incompleto. Tente novamente.')}}
async function deletePersonal(){showModal('Excluir dados locais?',`<p>Esta ação apagará marcadores, destaques, anotações, descobertas e progresso deste navegador. O romance continuará disponível.</p><div class="dialog-actions"><button class="button button-outline" data-action="close-modal">Cancelar</button><button class="button button-primary" data-action="confirm-delete">Excluir definitivamente</button></div>`)}
async function processAction(action,element){
 const id=element.dataset.id;
 if(action==='close-modal'){closeModal();return}
 if(action==='scroll-salas'){document.getElementById('salas')?.scrollIntoView({behavior:S.prefs.motion?'smooth':'auto',block:'start'});return}
 if(action==='open-film'){
  document.dispatchEvent(new Event('arquivo:pause-ambience'));
  showModal('Trailer',`<div class="film-dialog"><video controls playsinline preload="metadata" autoplay poster="/assets/video/trailer-poster.webp" aria-label="Trailer de Cartas do Norte, montado com as aquarelas da edição"><source src="${matchMedia('(orientation: portrait) and (max-width: 700px)').matches?'/assets/video/trailer-vertical.mp4':'/assets/video/trailer.mp4'}" type="video/mp4"/><track kind="captions" srclang="pt" label="Narração (português)" src="/assets/video/trailer.vtt"/></video><p>Trailer com aquarelas da edição e frases do próprio romance. Use fones de ouvido.</p></div>`);
  return;
 }
 if(action==='view-painting'){
   const a=entry(id);if(!a||!a.art||S.prefs.protected&&!(S.progress.completed.includes(id)||id===S.progress.current&&S.progress.seen[id]))return;
   focusBeforeDialog=document.activeElement;docViewer?.destroy();
   modalRoot.innerHTML=`<div class="viewer mat-mapa viewer-art" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><header class="viewer-head"><div class="viewer-title"><span class="eyebrow">Aquarela da edição · ${a.type==='chapter'?'Capítulo '+a.chapter:'Abertura'}</span><h2 id="viewer-title">${escapeHTML(a.title)}</h2></div><a class="button button-outline button-small viewer-read" href="${linkRead(a.id)}">Ir à leitura ↗</a><button class="icon-button viewer-close" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="viewer-body"><div class="viewer-stage"><div class="pz-frame" tabindex="0" aria-label="Aquarela ampliável"><div class="pz-layer"><img src="${a.art}" alt="Aquarela aprovada de ${escapeHTML(a.title)}"/></div></div>${zoomControls()}</div></div></div>`;
   document.body.style.overflow='hidden';docViewer=panZoom(modalRoot.querySelector('.pz-frame'),{onChange:zoomLabel(modalRoot)});modalRoot.querySelector('.viewer-close').focus();
   return;
 }
 if(action==='reader-toc'){tableOfContents();return}
 if(action==='reader-settings'){readerSettings();return}
 if(action==='reader-notes'){readerNotes();return}
 if(action==='bookmark'){await setBookmark();return}
 if(action==='complete'){await completeReading();return}
 if(action==='next-section'){const now=activeReader;const target=element.dataset.next;if(now&&entry(target)){S.progress.completed=[...new Set([...S.progress.completed,now])];await saveProgress();navigate('ler/'+target)}return}
 if(action==='manual-complete'){const current=S.progress.current;S.progress.completed=[...new Set([...S.progress.completed,current])];await saveProgress();toast('Entrada marcada como concluída.');render();return}
 if(action==='open-artifact'){await openArtifact(id,element.dataset.from||(routeInfo().route==='ler'?'ler':''));return}
 if(action==='skip-seal'){skipSeal();return}
 if(action==='break-seal'){await breakSeal(element.dataset.letter);return}
 if(action==='view-letter'){await viewLetter(id);return}
 if(action==='viewer-tab'){const body=modalRoot.querySelector('.viewer-body');if(body)body.dataset.tab=element.dataset.tab;modalRoot.querySelectorAll('.viewer-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b===element)));return}
 if(action==='atlas-place'){await showPlace(element.dataset.name);return}
 if(action==='view-plate'){const x=PLATES.find(p=>p.id===id);if(!x)return;focusBeforeDialog=document.activeElement;docViewer?.destroy();modalRoot.innerHTML=`<div class="viewer mat-mapa viewer-art" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><header class="viewer-head"><div class="viewer-title"><span class="eyebrow">${x.anchor?'Prancha · '+escapeHTML(entry(x.section)?.title||''):'Prancha avulsa'}</span><h2 id="viewer-title">${escapeHTML(x.caption)}</h2></div>${x.anchor?`<a class="button button-outline button-small viewer-read" href="${linkRead(x.section)}/${x.anchor}">Ir à passagem ↗</a>`:''}<button class="icon-button viewer-close" type="button" data-action="close-modal" aria-label="Fechar">${svg('close')}</button></header><div class="viewer-body"><div class="viewer-stage"><div class="pz-frame" tabindex="0" aria-label="Prancha ampliável"><div class="pz-layer"><img src="${x.src}" alt="${escapeHTML(x.alt)}"/></div></div>${zoomControls()}</div></div></div>`;document.body.style.overflow='hidden';docViewer=panZoom(modalRoot.querySelector('.pz-frame'),{onChange:zoomLabel(modalRoot)});modalRoot.querySelector('.viewer-close').focus();return}
 if(action==='open-person'){await openPerson(element.dataset.name);return}
 if(action==='begin-reading'){document.getElementById('read-start')?.scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'start'});return}
 if(action==='scroll-records'){document.getElementById('registros')?.scrollIntoView({behavior:reducedMotion()?'auto':'smooth'});return}
 if(action==='scene-sound'){document.dispatchEvent(new CustomEvent('arquivo:play-ambience',{detail:{sound:element.dataset.sound}}));return}
 if(action==='toggle-rose'){const nav=document.getElementById('rose-nav');const open=nav.hidden;nav.hidden=!open;element.setAttribute('aria-expanded',String(open));element.closest('.compass-instrument')?.classList.toggle('is-open',open);if(open)nav.querySelector('a')?.focus();return}
  if(action==='zoom-in'){(element.closest('.viewer')?docViewer:viewer)?.zoomBy(1.4);return}
 if(action==='zoom-out'){(element.closest('.viewer')?docViewer:viewer)?.zoomBy(1/1.4);return}
 if(action==='zoom-reset'){(element.closest('.viewer')?docViewer:viewer)?.reset();return}
 if(action==='hide-selection'){hideSelection();selectedRange=null;return}
 if(action==='add-highlight'){await saveMark('highlight');return}
 if(action==='add-note'){notesDialog();return}
 if(action==='save-note'){const text=modalRoot.querySelector('#note-text')?.value.trim();if(!text){toast('Escreva uma anotação antes de salvar.');return}await saveMark('note',text);return}
 if(action==='jump-mark'){const m=S.marks.find(x=>x.id===id);if(m){closeModal();if(activeReader!==m.section)navigate(`ler/${m.section}/${m.anchor}`);else document.getElementById(m.anchor)?.scrollIntoView({behavior:'smooth',block:'center'})}return}
 if(action==='delete-mark'){await db.remove(id,'marks');S.marks=S.marks.filter(x=>x.id!==id);toast('Marca excluída.');readerNotes();if(routeInfo().route==='ler')await render();return}
 if(action==='pref'){let v=element.dataset.value;await modifyPref(element.dataset.pref,v);return}
 if(action==='confirm-free'){S.prefs.protected=false;await savePrefs();closeModal();toast('Modo livre ativado.');render();return}
 if(action==='export-data'){await exportData();return}
 if(action==='import-data'){document.querySelector('#import-file')?.click();return}
 if(action==='clear-data'){await deletePersonal();return}
 if(action==='confirm-delete'){await db.reset();S.prefs={theme:'marfim',font:'serif',size:19,line:1.8,width:680,motion:true,protected:true};S.progress={current:'prologue',anchor:null,completed:[],seen:{},positions:{},lastReader:'prologue'};S.marks=[];S.discovered=[];S.letters=[];S.log={};S.places={};closeModal();toast('Dados locais excluídos.');render();return}
 if(action==='offline-text'){await prepareOffline('text');return}
 if(action==='offline-media'){await prepareOffline('media');return}
}
// Persistent event delegation keeps every menu and control functional across rerenders.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(button){e.preventDefault();try{await processAction(button.dataset.action,button)}catch(err){console.error(err);toast('Não foi possível completar a ação: '+err.message)}return}
 if(e.target.matches('[data-scrim]'))closeModal();
 if(e.target.closest('a[href^="#/"]')){const link=e.target.closest('a[href^="#/"]');if(link.hash===location.hash){closeModal();render()}else closeModal();hideSelection();}
});
document.addEventListener('change',async e=>{
 const el=e.target;if(el.id==='import-file'){await importData(el.files?.[0]);el.value='';return}
 const pref=el.dataset.pref;if(!pref)return;
 let val=el.type==='checkbox'?el.checked:el.value;if(['size','line','width'].includes(pref))val=Number(val);
 await modifyPref(pref,val);
});
document.addEventListener('input',e=>{if(e.target.id==='pref-size'){document.querySelector('#size-label').textContent=e.target.value+'px';document.documentElement.style.setProperty('--reading-size',e.target.value+'px')}});
document.addEventListener('submit',async e=>{if(e.target.id==='search-form'){e.preventDefault();await performSearch(e.target.querySelector('input').value)}});
document.addEventListener('keydown',e=>{
 if(e.key!=='Tab'||!modalRoot.querySelector('[aria-modal="true"]'))return;
 const items=[...modalRoot.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),summary,[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length);
 if(!items.length)return;
 const first=items[0],last=items[items.length-1];
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
 else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
});
document.addEventListener('pointerup',()=>setTimeout(handleSelection,50));document.addEventListener('keyup',e=>{if(e.key==='Escape'){closeModal();hideSelection()}else if(routeInfo().route==='ler')handleSelection()});
document.querySelector('#search-global').addEventListener('click',()=>navigate('busca'));
document.querySelector('#settings-global').addEventListener('click',()=>navigate('config'));
window.addEventListener('hashchange',()=>{if(main.querySelector('#reader-article')){updateReadingPosition();saveProgress()}window.removeEventListener('scroll',onReaderScroll);hideSelection();render()});
window.addEventListener('pagehide',()=>{if(routeInfo().route==='ler'){updateReadingPosition();saveProgress()}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&routeInfo().route==='ler'){updateReadingPosition();saveProgress()}});
async function boot(){try{C=await catalog();[P,PEOPLE,PLATES,LETTERS]=await Promise.all(['/content/places.json','/content/people.json','/content/plates.json','/content/letters.json'].map(u=>fetch(u).then(r=>r.ok?r.json():[]).catch(()=>[])));let prefs,progress,marks,discovered,migrated=false;try{[prefs,progress,marks,discovered,S.log,S.places,S.letters]=await Promise.all([db.get('prefs'),db.get('progress'),db.all('marks'),db.get('discovered'),db.get('log').then(v=>v||{}),db.get('places').then(v=>v||{}),db.get('letters').then(v=>Array.isArray(v)?v:[])])}catch(err){console.warn('Armazenamento local indisponível; leitura em modo temporário.',err);toast('O armazenamento local está bloqueado. Você poderá ler, mas o progresso desta sessão não será preservado.');}if(prefs)S.prefs={...S.prefs,...prefs};if(progress&&progress.edition!=='final'){const mig=await fetch('/content/migration-v4.json').then(r=>r.json()).catch(()=>null);if(mig){const sec=id=>mig.sections[id]||id,loc=(id,a)=>mig.anchors[id+'/'+a]||[sec(id),a],anc=(id,a)=>a&&loc(id,a)[1];const old=progress;progress={...old,current:sec(old.current),lastReader:sec(old.lastReader),completed:[...new Set((old.completed||[]).map(sec))],seen:{},positions:Object.fromEntries(Object.entries(old.positions||{}).map(([k,v])=>loc(k,v))),anchor:old.anchor&&(([s2,i2])=>({section:s2,id:i2}))(loc(old.anchor.section,old.anchor.id))};if(Array.isArray(marks))marks=marks.map(x=>{const [s2,a2]=x.anchor?loc(x.section,x.anchor):[sec(x.section),x.anchor];return {...x,section:s2,anchor:a2}});if(S.log)for(const v of Object.values(S.log))if(v.from)v.from=sec(v.from);migrated=true}progress.edition='final'}if(progress&&entry(progress.current))S.progress={...S.progress,...progress};if(Array.isArray(marks))S.marks=marks;if(Array.isArray(discovered))S.discovered=discovered;applyPrefs();if(migrated){saveProgress();for(const x of S.marks)db.put(x.id,x,'marks').catch(()=>{});toast('Seu progresso foi transferido para a Edição Final.')}if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('/sw.js').catch(()=>{})}if(!location.hash)location.hash='#/atrio';else await render()}catch(err){console.error(err);main.innerHTML=`<div class="page-container empty-state"><h2>O arquivo não pôde ser iniciado.</h2><p>${escapeHTML(err.message)}. Abra a aplicação por HTTPS ou localhost, e verifique o armazenamento do navegador.</p></div>`}}
// O botão de som da cena mostra o estado real do áudio (tocar ou pausar).
document.addEventListener('arquivo:ambience-state',e=>{document.querySelectorAll('.scene-sound').forEach(b=>{const on=e.detail.playing&&e.detail.sound===b.dataset.sound;b.setAttribute('aria-pressed',String(on));b.textContent=on?'Pausar o vento':'Ouvir o vento'})});
boot();
